using System;
using System.Windows;
using System.Windows.Controls;
using System.Diagnostics;
namespace LeafReader {
 public sealed partial class MainWindow {
  internal void ChangeLanguage(string language){Remember();State.Language=language;L10n.English=language=="en";Save();var book=Reader.Book;string query=search.Text;var parent=Reader.Parent as Panel;if(parent!=null)parent.Children.Remove(Reader);cards.ClearCoverCache();updating=true;Build();search.Text=query;ApplyTheme();if(book!=null){shelf.Visibility=Visibility.Collapsed;readerHost.Visibility=Visibility.Visible;bookTitle.Text=book.Title+" · "+L10n.T(book.SourceLabel??L10n.T("本地"));ReadingChanged();ReadingActivity(true);}updating=false;}
  internal void SettingsDialog(){idleTimer.Stop();SetReadingUiHidden(false);var d=Dialog(L10n.Pick("设置","Settings"),620,720);var stack=new StackPanel{Margin=new Thickness(24)};stack.Children.Add(Text(L10n.Pick("语言与界面","Language & interface"),20));stack.Children.Add(Text(L10n.Pick("界面语言","Interface language"),13));var language=new ComboBox{ItemsSource=new[]{"简体中文","English"},SelectedIndex=L10n.English?1:0,Margin=new Thickness(0,8,0,16)};language.SelectionChanged+=(s,e)=>{if(language.SelectedIndex<0)return;d.Close();ChangeLanguage(language.SelectedIndex==1?"en":"zh");SettingsDialog();};stack.Children.Add(language);
   var light=new CheckBox{Content=L10n.Pick("浅色背景","Light background"),IsChecked=State.Light,Margin=new Thickness(0,8,0,8)};light.Click+=(s,e)=>{State.Light=light.IsChecked==true;ApplyTheme();Save();};stack.Children.Add(light);
   var hide=new CheckBox{Content=L10n.Pick("自动隐藏阅读工具栏","Auto-hide reading controls"),IsChecked=State.AutoHide!=false,Margin=new Thickness(0,8,0,16)};hide.Click+=(s,e)=>{State.AutoHide=hide.IsChecked==true;Save();if(State.AutoHide==false){idleTimer.Stop();SetReadingUiHidden(false);}};stack.Children.Add(hide);stack.Children.Add(Text(L10n.Pick("新书默认模式","Default for new books"),13));var defaultMode=new ComboBox{ItemsSource=new[]{L10n.T("单页"),L10n.T("双页 · 左至右"),L10n.T("双页 · 右至左"),L10n.Pick("纵向连续","Vertical scrolling")},SelectedIndex=State.DefaultMode,Margin=new Thickness(0,8,0,16)};defaultMode.SelectionChanged+=(s,e)=>{if(defaultMode.SelectedIndex>=0){State.DefaultMode=defaultMode.SelectedIndex;Save();}};stack.Children.Add(defaultMode);
   var coverRule=new CheckBox{Content=L10n.Pick("双页模式：封面独页","Spreads: show cover alone"),IsChecked=Reader.Book!=null?Reader.Progress.Cover:State.CoverDefault!=false,Margin=new Thickness(0,8,0,8)};coverRule.Click+=(s,e)=>{State.CoverDefault=coverRule.IsChecked==true;if(Reader.Book!=null){Reader.Progress.Cover=State.CoverDefault==true;Reader.RefreshLayout();Remember();}Save();};stack.Children.Add(coverRule);var wideRule=new CheckBox{Content=L10n.Pick("双页模式：横图独页","Spreads: show wide pages alone"),IsChecked=Reader.Book!=null?Reader.Progress.Wide:State.WideDefault!=false,Margin=new Thickness(0,8,0,16)};wideRule.Click+=(s,e)=>{State.WideDefault=wideRule.IsChecked==true;if(Reader.Book!=null){Reader.Progress.Wide=State.WideDefault==true;Reader.RefreshLayout();Remember();}Save();};stack.Children.Add(wideRule);
   stack.Children.Add(Btn(L10n.T("管理来源"),ManageSources));stack.Children.Add(Btn(L10n.Pick("清理图片缓存","Clear image cache"),()=>{try{DiskCache.Clear();Reader.ClearImages();cards.ClearCoverCache();RenderShelf();MessageBox.Show(d,L10n.T("缓存已清理"));}catch(Exception ex){MessageBox.Show(d,ex.Message);}}));stack.Children.Add(Btn(L10n.Pick("操作说明","Reader help"),Help));
   var banner=new Border{Background=R("Panel"),CornerRadius=new CornerRadius(12),Padding=new Thickness(18),Margin=new Thickness(0,22,0,12)};var support=new StackPanel();support.Children.Add(Text(L10n.Pick("支持 Leaf Reader  ♡","Support Leaf Reader  ♡"),18));support.Children.Add(Text(L10n.Pick("自愿支持开发；所有阅读功能保持免费。","Voluntary support; all reading features remain free."),12,"Muted"));support.Children.Add(Btn(L10n.Pick("赞助与支持","Sponsorship & support"),()=>{if(SupportLinks.Kofi.Length==0&&SupportLinks.Afdian.Length==0){MessageBox.Show(d,L10n.Pick("赞助主页尚未开放。感谢你的使用、问题反馈和代码贡献！","Sponsorship pages are not open yet. Thank you for using Leaf Reader, reporting issues and contributing code!"));return;}var pick=Dialog(L10n.Pick("支持项目","Support the project"),400,230);var links=new StackPanel{Margin=new Thickness(22)};if(SupportLinks.Kofi.Length>0)links.Children.Add(Btn("Ko-fi",()=>Process.Start(new ProcessStartInfo(SupportLinks.Kofi){UseShellExecute=true})));if(SupportLinks.Afdian.Length>0)links.Children.Add(Btn(L10n.T("爱发电 / Afdian"),()=>Process.Start(new ProcessStartInfo(SupportLinks.Afdian){UseShellExecute=true})));pick.Content=links;pick.ShowDialog();}));banner.Child=support;stack.Children.Add(banner);stack.Children.Add(Text("Leaf Reader 2.3.1 preview · ricefriend · MIT",12,"Muted"));stack.Children.Add(Btn(L10n.T("关闭"),()=>d.Close()));d.Content=new ScrollViewer{Content=stack,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};d.SetResourceReference(Window.BackgroundProperty,"Bg");d.SetResourceReference(Window.ForegroundProperty,"Fg");d.ShowDialog();ReadingActivity(true);
  }
 }
 public static class SupportLinks {public static readonly string Kofi="https://ko-fi.com/gdbkf",Afdian="";}
}
